import { readFileSync } from "node:fs";

import { expect, test, type Locator, type Page } from "@playwright/test";

import { mockLangGraphAPI } from "./utils/mock-api";

// Generated by the real synthetic intake API; backend tests independently
// verify source receipts, strict parser, ALL counts and archive hashes.
const fixture = JSON.parse(
  readFileSync(
    new URL("../fixtures/synthetic-external-qa.json", import.meta.url),
    "utf8",
  ),
);
const receipt = fixture.receipt;
const base = "/api/evaluation/projects/" + receipt.project_id;
const intakePath = base + "/external-qa-intakes/" + receipt.id;
const createLabel = "Quarantine technical declarations";
const reconcileLabel = "Reconcile same intake ID by GET";
const consents = [
  "I confirm the exact historical export and original run ID.",
  "I confirm these two files contain technical metadata only, not outputs, QA, keys or journals.",
  "I acknowledge this untrusted declaration is not evidence, approval or execution authority.",
];
const panel = (page: Page) =>
  page.getByRole("region", {
    name: "External QA technical quarantine",
    exact: true,
  });
async function setup(page: Page) {
  mockLangGraphAPI(page, { threads: [] });
  await page.addInitScript(
    (id: string) =>
      Object.defineProperty(Crypto.prototype, "randomUUID", {
        value: () =>
          id.slice(0, 8) +
          "-" +
          id.slice(8, 12) +
          "-" +
          id.slice(12, 16) +
          "-" +
          id.slice(16, 20) +
          "-" +
          id.slice(20),
      }),
    receipt.id,
  );
  const requests: string[] = [],
    forbidden: string[] = [];
  page.on("request", (request) => {
    if (
      /example\.test|\/gold(?:\?|$|\/)|\/reference-answers|\/api\/component-tests|\/api\/reports\/assistant/.test(
        request.url(),
      )
    )
      forbidden.push(request.url());
  });
  await page.route("**/api/evaluation/**", async (route) => {
    const request = route.request(),
      path = new URL(request.url()).pathname;
    requests.push(request.method() + " " + path);
    if (path === "/api/evaluation/projects")
      return route.fulfill({
        json: {
          projects: [
            { id: receipt.project_id, name: "Synthetic quarantine project" },
            { id: "p2", name: "Other project" },
          ],
        },
      });
    if (path.endsWith("/datasets"))
      return route.fulfill({ json: { datasets: [] } });
    if (path === base + "/exports/" + fixture.export_receipt.id)
      return route.fulfill({ json: fixture.export_receipt });
    if (path === base + "/plans/" + fixture.plan.id)
      return route.fulfill({ json: fixture.plan });
    if (path === intakePath) {
      if (request.method() === "PUT")
        expect(request.postDataJSON()).toEqual(fixture.request);
      else expect(request.method()).toBe("GET");
      return route.fulfill({ json: receipt });
    }
    if (path === intakePath + "/audit") {
      expect(request.method()).toBe("GET");
      expect(new URL(request.url()).searchParams.toString()).toBe(
        "after_sequence=0&limit=50",
      );
      return route.fulfill({ json: fixture.audit });
    }
    forbidden.push(request.method() + " " + path);
    return route.fulfill({
      status: 404,
      json: { detail: "Unexpected synthetic route" },
    });
  });
  await page.goto("/workspace/datasets");
  await page
    .getByRole("combobox", { name: "Select project", exact: true })
    .selectOption(receipt.project_id);
  await expect(panel(page)).toBeVisible();
  expect(
    requests.filter((r) =>
      /\/exports\/|\/plans\/|\/external-qa-intakes\/|export-capabilities/.test(
        r,
      ),
    ),
  ).toEqual([]);
  return { requests, forbidden };
}
async function prepare(region: Locator, raw = fixture.request.receipt_json) {
  await region
    .getByLabel("Exact historical export ID", { exact: true })
    .fill(fixture.export_receipt.id);
  await region
    .getByRole("button", {
      name: "Open historical export and frozen plan",
      exact: true,
    })
    .click();
  await expect(
    region.getByText("Historical baseline source opened", { exact: true }),
  ).toBeVisible();
  await region
    .getByLabel("Original external run UUID", { exact: true })
    .fill(fixture.request.original_run_id);
  await region.getByLabel("Receipt JSON file", { exact: true }).setInputFiles({
    name: "identity.json",
    mimeType: "application/json",
    buffer: Buffer.from(raw),
  });
  await region
    .getByLabel("Reconciliation JSON file", { exact: true })
    .setInputFiles({
      name: "reconciliation.json",
      mimeType: "application/json",
      buffer: Buffer.from(fixture.request.reconciliation_json),
    });
  await region
    .getByRole("button", {
      name: "Inspect selected technical documents",
      exact: true,
    })
    .click();
}
async function confirm(region: Locator) {
  await expect(
    region.getByText("Technical inspection only — NOT_EVALUATED", {
      exact: true,
    }),
  ).toBeVisible();
  const create = region.getByRole("button", { name: createLabel, exact: true });
  for (const label of consents) {
    await expect(create).toBeDisabled();
    await region.getByRole("checkbox", { name: label, exact: true }).check();
  }
  await expect(create).toBeEnabled();
  return create;
}
for (const width of [1440, 390])
  test(
    "explicit technical-only creation, keyboard and no persistent cache at " +
      width +
      "px",
    async ({ page }) => {
      await page.setViewportSize({ width, height: 950 });
      const { requests, forbidden } = await setup(page),
        region = panel(page);
      await prepare(region);
      const create = await confirm(region);
      await create.focus();
      await page.keyboard.press("Enter");
      await expect(
        region.getByText("Historical quarantine receipt — NOT_EVALUATED", {
          exact: true,
        }),
      ).toBeVisible();
      expect(requests.filter((r) => r.startsWith("PUT "))).toEqual([
        "PUT " + intakePath,
      ]);
      expect(
        requests.filter((r) => /bundle|export-capabilities|audit/.test(r)),
      ).toEqual([]);
      const persisted = await page.evaluate(() =>
        JSON.stringify([
          Object.values(localStorage),
          Object.values(sessionStorage),
        ]),
      );
      expect(persisted).not.toContain(fixture.request.receipt_json);
      expect(persisted).not.toContain(receipt.archive_hash);
      await expect(region.getByRole("checkbox").first()).not.toBeChecked();
      expect(
        await page.evaluate(() => document.documentElement.scrollWidth),
      ).toBeLessThanOrEqual(width + 1);
      expect(forbidden).toEqual([]);
    },
  );
test("lost acknowledgement and same-ID GET404 survive project switches without resend", async ({
  page,
}) => {
  const { forbidden } = await setup(page);
  let writes = 0,
    reads = 0;
  await page.route("**" + intakePath, (route) => {
    if (route.request().method() === "PUT") {
      writes++;
      expect(route.request().postDataJSON()).toEqual(fixture.request);
      return route.fulfill({ status: 503, json: { detail: "unknown" } });
    }
    reads++;
    return reads === 1
      ? route.fulfill({ status: 404, json: { detail: "unknown" } })
      : route.fulfill({ json: receipt });
  });
  await prepare(panel(page));
  await (await confirm(panel(page))).click();
  await expect(panel(page).getByRole("status")).toContainText(receipt.id);
  await panel(page)
    .getByRole("button", { name: reconcileLabel, exact: true })
    .click();
  await expect(panel(page).getByRole("alert")).toBeVisible();
  await page
    .getByRole("combobox", { name: "Select project", exact: true })
    .selectOption("p2");
  await expect(panel(page).getByRole("status")).toHaveCount(0);
  await page
    .getByRole("combobox", { name: "Select project", exact: true })
    .selectOption(receipt.project_id);
  await expect(panel(page).getByRole("status")).toContainText(receipt.id);
  await expect(
    panel(page).getByRole("button", { name: createLabel, exact: true }),
  ).toBeDisabled();
  expect(reads).toBe(1);
  expect(writes).toBe(1);
  await panel(page)
    .getByRole("button", { name: reconcileLabel, exact: true })
    .click();
  await expect(panel(page).getByRole("status")).toHaveCount(0);
  await expect(
    panel(page).getByText("Historical quarantine receipt — NOT_EVALUATED", {
      exact: true,
    }),
  ).toBeVisible();
  expect(reads).toBe(2);
  expect(writes).toBe(1);
  expect(forbidden).toEqual([]);
});
test("historical intake and audit open explicitly without current grants or source reads", async ({
  page,
}) => {
  const { requests, forbidden } = await setup(page),
    region = panel(page);
  await region
    .getByLabel("Exact historical intake ID", { exact: true })
    .fill(receipt.id);
  await region
    .getByRole("button", {
      name: "Open historical quarantine receipt",
      exact: true,
    })
    .click();
  await expect(
    region.getByText("Historical quarantine receipt — NOT_EVALUATED", {
      exact: true,
    }),
  ).toBeVisible();
  await region
    .getByRole("button", { name: "Load quarantine audit", exact: true })
    .click();
  await expect(region.locator("pre").last()).toContainText(
    "metadata_quarantined",
  );
  expect(requests.filter((r) => r.includes("/external-qa-intakes/"))).toEqual([
    "GET " + intakePath,
    "GET " + intakePath + "/audit",
  ]);
  expect(
    requests.filter((r) => /export-capabilities|\/exports\/|\/plans\//.test(r)),
  ).toEqual([]);
  expect(forbidden).toEqual([]);
});
test("malformed successful authority claims retain pending and allow only original-ID reconciliation", async ({
  page,
}) => {
  await setup(page);
  let writes = 0;
  await page.route("**" + intakePath, (route) => {
    if (route.request().method() === "PUT") {
      writes++;
      return route.fulfill({ json: { ...receipt, approval_granted: true } });
    }
    return route.fulfill({ json: receipt });
  });
  await prepare(panel(page));
  await (await confirm(panel(page))).click();
  await expect(panel(page).getByRole("alert")).toBeVisible();
  await expect(panel(page).getByRole("status")).toContainText(receipt.id);
  await expect(
    panel(page).getByText("Historical quarantine receipt — NOT_EVALUATED", {
      exact: true,
    }),
  ).toHaveCount(0);
  await panel(page)
    .getByRole("button", { name: reconcileLabel, exact: true })
    .click();
  await expect(panel(page).getByRole("status")).toHaveCount(0);
  expect(writes).toBe(1);
});
test("duplicate technical fields fail locally without PUT or authority", async ({
  page,
}) => {
  const { requests, forbidden } = await setup(page);
  await prepare(
    panel(page),
    fixture.request.receipt_json.replace(
      '"verdict":',
      '"verdict":"NOT_EVALUATED","verdict":',
    ),
  );
  await expect(panel(page).getByRole("alert")).toBeVisible();
  await expect(
    panel(page).getByRole("button", { name: createLabel, exact: true }),
  ).toBeDisabled();
  expect(requests.filter((r) => r.startsWith("PUT "))).toEqual([]);
  expect(forbidden).toEqual([]);
});
